import{_ as t,o as r,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Crimson/SeaStore Meeting 2023-02-22","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore Meeting 2023-02-22","date":"2023-02-22T00:00:00.000Z","updated":"2023-02-24T00:00:00.000Z","tags":["Ceph","distributed storage","Crimson","SeaStore","storage cluster"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-02-22.md","filePath":"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-02-22.md","lastUpdated":1780460162000}'),a={name:"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-02-22.md"};function n(i,e,l,_,g,h){return r(),o("div",null,[...e[0]||(e[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>日期：</strong> 2023-02-22 <strong>参会人员：</strong> [参会人员名单]</p><h4 id="_1-研发进展报告" tabindex="-1">1. 研发进展报告 <a class="header-anchor" href="#_1-研发进展报告" aria-label="Permalink to &quot;1. 研发进展报告&quot;">​</a></h4><ul><li><strong>scrub 和 crimson 工作进展：</strong> 目前研发团队专注于 scrub 工作和 crimson 相关的开发。</li><li><strong>弱事务问题：</strong> 正在审查 Johan 发现的弱事务问题，目前有四到五个相关的 Pull Request (PR) 待处理。</li><li><strong>多信使扩展：</strong> 正在进行 socket 和 socket 测试的扩展工作，并继续进行清理工作。</li></ul><h4 id="_2-qe-部门更新" tabindex="-1">2. QE 部门更新 <a class="header-anchor" href="#_2-qe-部门更新" aria-label="Permalink to &quot;2. QE 部门更新&quot;">​</a></h4><ul><li><strong>物理节点测试：</strong> 由于物理节点设置存在问题，已收到新机器并开始进行基本随机测试。初步测试运行良好，未见重大故障。</li><li><strong>RBT 测试问题：</strong> 之前提到的 RBT 测试问题因机器崩溃暂时无法追踪，将在完成 rados 测试后重新生成问题并创建 Checkers。</li></ul><h4 id="_3-医疗系统接口讨论" tabindex="-1">3. 医疗系统接口讨论 <a class="header-anchor" href="#_3-医疗系统接口讨论" aria-label="Permalink to &quot;3. 医疗系统接口讨论&quot;">​</a></h4><ul><li><strong>当前实现架构：</strong> 每个 OSD 和共享服务持有单个强实例引用，通过 store 接口访问。</li><li><strong>未来改进建议：</strong> 建议将 store 接口分离为两部分，一部分供主 OSD 使用，另一部分供其他 OSD 使用。</li><li><strong>讨论焦点：</strong> 讨论了是否需要在 OSD 中直接使用 core zero shortstore，以及如何处理未来可能的动态空间分配问题。</li><li><strong>决定：</strong> 决定保持当前实现，但未来可能需要考虑动态空间分配的实现方式。</li></ul><h4 id="_4-后续行动计划" tabindex="-1">4. 后续行动计划 <a class="header-anchor" href="#_4-后续行动计划" aria-label="Permalink to &quot;4. 后续行动计划&quot;">​</a></h4><ul><li><strong>代码修改：</strong> 根据讨论结果，进行必要的代码修改以支持新的架构。</li><li><strong>测试和验证：</strong> 继续进行测试，确保新的实现稳定可靠。</li><li><strong>文档更新：</strong> 更新相关文档，确保用户和开发者能够理解新的架构和使用方法。</li></ul><p><strong>下次会议：</strong> [具体日期]</p><p><strong>备注：</strong> 下次会议将讨论如何使用 ceph-ansible 部署 crimson，并寻求社区的帮助和反馈。</p><p>[改进后的中文总结内容结束]</p>',13)])])}const p=t(a,[["render",n]]);export{d as __pageData,p as default};
